output:
1: $ErrorActionPreference = 'Stop'
2: $taskSource = $PSScriptRoot
3: $taskRun = Join-Path $taskSource 'reliability-request-stream-fake01'
4: $taskPython = 'C:\Python314\python.exe'
5: $taskNative = $null
6: $taskRunStarted = [DateTimeOffset]::UtcNow.ToString('o')
7: $taskClock = [Diagnostics.Stopwatch]::StartNew()
8: 
9: function Write-TaskJson([string]$taskPath, $taskValue) {
10:     $taskBytes = [Text.UTF8Encoding]::new($false).GetBytes(($taskValue | ConvertTo-Json -Depth 24) + "`n")
11:     $taskStream = [IO.FileStream]::new($taskPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::Read)
12:     try { $taskStream.Write($taskBytes); $taskStream.Flush($true) } finally { $taskStream.Dispose() }
13: }
14: function Get-TaskBinding([string]$taskPath) {
15:     $taskItem = Get-Item -LiteralPath $taskPath -ErrorAction Stop
16:     if ($taskItem.PSIsContainer -or ($taskItem.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Plain pinned input required' }
17:     return [ordered]@{ bytes = $taskItem.Length; sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $taskPath).Hash.ToLowerInvariant() }
18: }
19: 
20: if (Test-Path -LiteralPath $taskRun) { throw 'Fresh reliability-request-stream-fake01 output required' }
21: $taskPinsPath = Join-Path $taskSource 'PINS.json'
22: $taskAdmissionPath = Join-Path $taskSource 'ROOT-ADMISSION.json'
23: $taskPinsBinding = Get-TaskBinding $taskPinsPath
24: $taskAdmissionBinding = Get-TaskBinding $taskAdmissionPath
25: $taskLauncherBinding = Get-TaskBinding $PSCommandPath
26: $taskPins = Get-Content -LiteralPath $taskPinsPath -Raw | ConvertFrom-Json
27: $taskAdmission = Get-Content -LiteralPath $taskAdmissionPath -Raw | ConvertFrom-Json
28: if ($taskAdmission.approved -cne $true -or $taskAdmission.label -cne 'reliability-request-stream-fake01' -or
29:     $taskAdmission.pins_sha256 -cne $taskPinsBinding.sha256 -or
30:     $taskAdmission.scope -cne 'generated_bytes_and_fake_ports_only') { throw 'Exact root admission required' }
31: if ($taskPins.finalized -cne $true -or @($taskPins.files | Where-Object { $_.status -ceq 'pending_author_freeze' }).Count -ne 0) {
32:     throw 'Source preparation remains pending; no launch admitted'
33: }
34: $taskRows = @($taskPins.files)
35: if ($taskRows.Count -ne 13 -or @($taskRows.path | Sort-Object -Unique).Count -ne 13) { throw 'Exact 13-entry input map required' }
36: $taskBefore = @()
37: foreach ($taskRow in $taskRows) {
38:     if ($taskRow.path -cnotmatch '^[A-Za-z0-9_.-]+$') { throw 'Flat input name required' }
39:     $taskPath = Join-Path $taskSource $taskRow.path
40:     $taskActual = Get-TaskBinding $taskPath
41:     if ($taskActual.sha256 -cne $taskRow.sha256 -or $taskActual.bytes -ne $taskRow.bytes) { throw 'Pinned input mismatch' }
42:     $taskBefore += [ordered]@{ name = $taskRow.path; bytes = $taskActual.bytes; sha256 = $taskActual.sha256 }
43: }
44: New-Item -ItemType Directory -Path $taskRun -ErrorAction Stop | Out-Null
45: foreach ($taskRow in $taskRows) { Copy-Item -LiteralPath (Join-Path $taskSource $taskRow.path) -Destination (Join-Path $taskRun $taskRow.path) -ErrorAction Stop }
46: Copy-Item -LiteralPath $taskPinsPath -Destination (Join-Path $taskRun 'PINS.json') -ErrorAction Stop
47: Copy-Item -LiteralPath $taskAdmissionPath -Destination (Join-Path $taskRun 'ROOT-ADMISSION.json') -ErrorAction Stop
48: $taskControls = @(
49:     [ordered]@{name='PINS.json'; binding=$taskPinsBinding},
50:     [ordered]@{name='ROOT-ADMISSION.json'; binding=$taskAdmissionBinding},
51:     [ordered]@{name='run_fake11_01.ps1'; binding=$taskLauncherBinding}
52: )
53: foreach ($taskRow in $taskBefore) {
54:     $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskRow.name)
55:     if ($taskCopy.sha256 -cne $taskRow.sha256 -or $taskCopy.bytes -ne $taskRow.bytes) { throw 'Copied input mismatch' }
56: }
57: foreach ($taskControl in $taskControls) {
58:     $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskControl.name)
59:     if ($taskCopy.sha256 -cne $taskControl.binding.sha256 -or $taskCopy.bytes -ne $taskControl.binding.bytes) { throw 'Copied control mismatch' }
60: }
61: $taskRemovedNames = @()
62: foreach ($taskEnv in @(Get-ChildItem Env:)) {
63:     if ($taskEnv.Name -match '(?i)(ANTHROPIC|OPENAI|GEMINI|GOOGLE_API|GROK|XAI|AZURE_OPENAI|HF_TOKEN|HUGGING_FACE|API_KEY|ACCESS_TOKEN|PROXY|PYTHONPATH|PYTHONHOME|PYTHONSTARTUP|PYTHONUSERBASE|VIRTUAL_ENV)') {
64:         $taskRemovedNames += $taskEnv.Name
65:         Remove-Item -LiteralPath ('Env:' + $taskEnv.Name)
66:     }
67: }
68: $env:IG_FORBIDDEN_LIVE = 'C:\Users\hello\AppData\Local\Uoink\index.db'
69: Write-TaskJson (Join-Path $taskRun 'plan.json') ([ordered]@{
70:     schema='uoink.reliability-request-stream-fake-launch.v1'; label='reliability-request-stream-fake01'; python=$taskPython;
71:     arguments=@('-I','-S','-B',(Join-Path $taskRun 'qualify_reliability.py'));
72:     started_utc=$taskRunStarted; before=$taskBefore; controls=$taskControls;
73:     removed_environment_names=$taskRemovedNames; startup_binding_set=$true;
74:     scope='generated_bytes_and_fake_ports_only'
75: })
76: 
77: try {
78:     $PSNativeCommandUseErrorActionPreference = $false
79:     & $taskPython -I -S -B (Join-Path $taskRun 'qualify_reliability.py') 1> (Join-Path $taskRun 'stdout.json') 2> (Join-Path $taskRun 'stderr.log')
80:     $taskNative = $global:LASTEXITCODE
81:     Write-TaskJson (Join-Path $taskRun 'native-exit.json') ([ordered]@{
82:         native_exit=$taskNative; finished_utc=[DateTimeOffset]::UtcNow.ToString('o');
83:         elapsed_seconds=$taskClock.Elapsed.TotalSeconds
84:     })
85:     $taskAfter = @()
86:     foreach ($taskRow in $taskBefore) {
87:         $taskOriginal = Get-TaskBinding (Join-Path $taskSource $taskRow.name)
88:         $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskRow.name)
89:         $taskAfter += [ordered]@{name=$taskRow.name; original=$taskOriginal; copy=$taskCopy;
90:             unchanged=($taskOriginal.sha256 -ceq $taskRow.sha256 -and $taskCopy.sha256 -ceq $taskRow.sha256 -and
91:                 $taskOriginal.bytes -eq $taskRow.bytes -and $taskCopy.bytes -eq $taskRow.bytes)}
92:     }
93:     $taskAfterControls = @()
94:     foreach ($taskControl in $taskControls) {
95:         $taskOriginal = Get-TaskBinding (Join-Path $taskSource $taskControl.name)
96:         $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskControl.name)
97:         $taskAfterControls += [ordered]@{name=$taskControl.name; original=$taskOriginal; copy=$taskCopy;
98:             unchanged=($taskOriginal.sha256 -ceq $taskControl.binding.sha256 -and $taskCopy.sha256 -ceq $taskControl.binding.sha256 -and
99:                 $taskOriginal.bytes -eq $taskControl.binding.bytes -and $taskCopy.bytes -eq $taskControl.binding.bytes)}
100:     }
101:     $taskInputsOkay = @($taskAfter | Where-Object { $_.unchanged -ne $true }).Count -eq 0 -and
102:         @($taskAfterControls | Where-Object { $_.unchanged -ne $true }).Count -eq 0
103:     Write-TaskJson (Join-Path $taskRun 'input-check.json') ([ordered]@{inputs=$taskAfter; controls=$taskAfterControls; inputs_unchanged=$taskInputsOkay})
104:     $taskStdout = Get-Item -LiteralPath (Join-Path $taskRun 'stdout.json')
105:     $taskStderr = Get-Item -LiteralPath (Join-Path $taskRun 'stderr.log')
106:     if ($taskStdout.Length -gt 262144) { throw 'Raw receipt exceeds bound' }
107:     $taskResult = Get-Content -LiteralPath $taskStdout.FullName -Raw | ConvertFrom-Json
108:     $taskExpected = @(Get-Content -LiteralPath (Join-Path $taskRun 'EXPECTED-CASES.json') -Raw | ConvertFrom-Json)
109:     $taskCaseIds = @($taskResult.cases | ForEach-Object { $_.id })
110:     $taskMembership = ($taskCaseIds.Count -eq 11 -and $taskExpected.Count -eq 11 -and
111:         (($taskCaseIds | ConvertTo-Json -Compress) -ceq ($taskExpected | ConvertTo-Json -Compress)))
112:     $taskGuardsOkay = @($taskResult.guards.PSObject.Properties).Count -eq 10 -and
113:         @($taskResult.guards.PSObject.Properties | Where-Object { $_.Value -cne $true }).Count -eq 0
114:     $taskValid = ($taskNative -is [int] -and $taskNative -eq 0 -and $taskResult.qualification_exit -eq 0 -and
115:         $taskResult.passed -eq 11 -and $taskResult.failed -eq 0 -and $taskResult.skipped -eq 0 -and
116:         $taskMembership -and $taskGuardsOkay -and $taskResult.guard_valid -ceq $true -and
117:         $taskResult.membership_valid -ceq $true -and $taskInputsOkay -and $taskStderr.Length -eq 0 -and
118:         @($taskResult.guard_denials).Count -eq 0 -and @($taskResult.registry_denials).Count -eq 0)
119:     Write-TaskJson (Join-Path $taskRun 'exit.json') ([ordered]@{
120:         native_exit=$taskNative; qualification_exit=$taskResult.qualification_exit;
121:         valid=$taskValid; inputs_unchanged=$taskInputsOkay; membership_valid=$taskMembership;
122:         guards_valid=$taskGuardsOkay; passed=$taskResult.passed; failed=$taskResult.failed; skipped=$taskResult.skipped;
123:         stdout_bytes=$taskStdout.Length; stderr_bytes=$taskStderr.Length;
124:         finished_utc=[DateTimeOffset]::UtcNow.ToString('o'); elapsed_seconds=$taskClock.Elapsed.TotalSeconds
125:     })
126:     if (-not $taskValid) { exit 1 }
127:     Write-Output 'reliability-request-stream-fake01: 11 passed, 0 failed, 0 skipped; generated scope only.'
128:     exit 0
129: } catch {
130:     Write-TaskJson (Join-Path $taskRun 'launch-failure.json') ([ordered]@{
131:         native_exit=$taskNative; failure_type=$_.Exception.GetType().FullName;
132:         message=$_.Exception.Message; finished_utc=[DateTimeOffset]::UtcNow.ToString('o')
133:     })
134:     throw
135: }
